import{_ as a,o,c as t,a5 as i}from"./chunks/framework.BwlBv862.js";const m=JSON.parse('{"title":"Adaptar recetas de automatización","description":"","frontmatter":{"title":"Adaptar recetas de automatización","docId":"user.automations.recipes","translationKey":"user.automations.recipes","locale":"es","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"43a103ef68e43d691eec2214ffefb5e2e0e6b663afa9f4e63b5dac0ccec162ea","translationRevision":"62260f3a7dbf8660eb393810941b3772ec6787a7a86f07ec07050f6f30a19df7","order":30},"headers":[],"relativePath":"es/user/automations/recipes.md","filePath":"es/user/automations/recipes.md","lastUpdated":1794611623000}'),n={name:"es/user/automations/recipes.md"};function s(r,e,c,d,l,u){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="adapt-practical-automation-recipes" tabindex="-1">Adaptar recetas de automatización <a class="header-anchor" href="#adapt-practical-automation-recipes" aria-label="Permalink to &quot;Adaptar recetas de automatización {#adapt-practical-automation-recipes}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Convierte una <a href="./first-rule.html">regla de registro</a> funcional en reacciones con condiciones concretas. Necesitas un perfil activo y campos de eventos observados. Comienza con acciones <code>core.log</code>; sustituye su efecto únicamente después de confirmar coincidencias y frecuencia.</p><h2 id="match-a-chat-command" tabindex="-1">Reconocer un comando de chat <a class="header-anchor" href="#match-a-chat-command" aria-label="Permalink to &quot;Reconocer un comando de chat {#match-a-chat-command}&quot;">​</a></h2><p>Crea un evento <code>tiktok.chat</code> con <code>event.data.comment</code> igual (<code>eq</code>) a <code>!hello</code>. Registra:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hola {{ event.user.uniqueId }}</span></span></code></pre></div><p>Usa una espera por usuario de <code>30</code> segundos: limita la repetición de un espectador y permite que otro tenga su oportunidad independiente. La igualdad exacta resulta útil para comandos; la comparación de contenido también acepta mensajes con texto adicional. Elige según tu intención.</p><h2 id="record-a-qualifying-gift" tabindex="-1">Registrar un regalo que cumpla el umbral <a class="header-anchor" href="#record-a-qualifying-gift" aria-label="Permalink to &quot;Registrar un regalo que cumpla el umbral {#record-a-qualifying-gift}&quot;">​</a></h2><p>Crea un evento <code>tiktok.gift</code> con <code>event.data.diamondCount</code> mayor o igual (<code>gte</code>) a <code>10</code>. Registra:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Regalo {{ event.data.giftName }} de {{ event.user.uniqueId }}</span></span></code></pre></div><p>Inspecciona primero los detalles reales. El valor en diamantes, las repeticiones y el indicador de finalización son campos distintos. Si necesitas reaccionar solo al finalizar, comprueba que llega <code>event.data.repeatEnd</code> y añade la condición booleana verdadera. Un filtro por nombre no garantiza una ejecución por combo terminado.</p><h2 id="bound-a-shared-reaction" tabindex="-1">Limitar una reacción compartida <a class="header-anchor" href="#bound-a-shared-reaction" aria-label="Permalink to &quot;Limitar una reacción compartida {#bound-a-shared-reaction}&quot;">​</a></h2><p>Crea un evento <code>tiktok.follow</code> con espera global de <code>10</code> segundos. Vincula una acción de registro breve. Si dos espectadores siguen durante ese intervalo, la espera global puede omitir la segunda reacción. Usa el ámbito por usuario si cada espectador necesita un límite independiente.</p><p>Para varias acciones, ordena la lista y conserva el modo de todas las acciones cuando necesites cada paso. El modo aleatorio elige una acción; no ejecuta todos los pasos en orden aleatorio. Añade <code>core.delay</code> únicamente cuando los pasos posteriores deban esperar.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado y estado {#expected-result-and-status}&quot;">​</a></h2><p>Estos disparadores, filtros y tiempos de espera están disponibles en el motor local. Una ejecución debe corresponder a un evento aceptado y coincidente, sujeto a la espera y los interruptores. La aceptación del proveedor todavía requiere una comprobación LIVE real.</p><h2 id="recovery" tabindex="-1">Recuperación <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperación {#recovery}&quot;">​</a></h2><p>Si falla una receta, vuelve a una sola acción de registro, inspecciona los datos y simplifica temporalmente las condiciones. Evita quitar los límites durante una emisión concurrida. Las pruebas de audio, puntos, HTTP y plugins pueden producir efectos reales. Consulta <a href="./../plugins/audio.html">audio</a>, <a href="./variables.html">variables</a> y <a href="./../preferences/troubleshooting.html">diagnósticos</a> antes de añadir esas dependencias.</p>',18)])])}const h=a(n,[["render",s]]);export{m as __pageData,h as default};
